interface IconProps {
  size?: number;
  stroke?: number;
  fill?: string;
  strokeColor?: string;
  style?: React.CSSProperties;
}

function Ic({
  d,
  size = 16,
  stroke = 1.6,
  fill = "none",
  strokeColor = "currentColor",
  style,
}: IconProps & { d: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={fill}
      stroke={strokeColor}
      strokeWidth={stroke}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={style}
      aria-hidden="true"
    >
      {d}
    </svg>
  );
}

