// ── Provider logos (monochrome, fill=currentColor) ──

function LogoIc({ d, size = 18 }: { d: React.ReactNode; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      {d}
    </svg>
  );
}

